// 🧹 CLEAN DATA FOR AI
// We prepare the data to be unambiguous for the AI.

const items = $input.all();
const results = [];

for (const item of items) {
    const content = item.json.content;
    const rawLinks = item.json.links || [];

    // Sanitization: Keep only what's needed.
    // Rename 'claim' to 'target_sentence_part' to guide the AI to find the container sentence.
    const cleanLinks = rawLinks.map(link => ({
        target_sentence_part: link.claim,
        link_text: link.anchor,
        url: link.url
    }));

    results.push({
        json: {
            content,
            links: cleanLinks
        }
    });
}

return results;
